function registerPsLogsCommand(pi, manager) {
  pi.registerCommand("ps:logs", {
    description: "Open log viewer for a process (search, scroll, stream filter)",
    getArgumentCompletions: allProcessCompletions(manager),
    handler: async (args, ctx) => {
      if (!ctx.hasUI) return;
      const arg = args.trim();
      let processId;
      if (arg) {
        const proc = manager.get(arg);
        if (!proc) return;
        processId = proc.id;
      }
      await ctx.ui.custom(
        (_tui, theme, _kb, done) => {
          return new LogOverlayComponent({
            tui: _tui,
            theme,
            manager,
            initialProcessId: processId,
            done: () => done(null)
          });
        },
        {
          overlay: true,
          overlayOptions: {
            width: "90%",
            maxHeight: "80%",
            anchor: "center"
          }
        }
      );
    }
  });
}

// ../../../../.pi/agent/npm/node_modules/@aliou/pi-processes/src/commands/pin/command.ts
function registerPsPinCommand(pi, manager, dockActions) {
  pi.registerCommand("ps:pin", {
    description: "Pin the dock to a specific process",
    getArgumentCompletions: allProcessCompletions(manager),
    handler: async (args, ctx) => {
      const arg = args.trim();
      let processId;
      if (arg) {
        const proc = manager.get(arg);
        if (!proc) {
          return;
        }
        processId = proc.id;
      } else {
        processId = await pickProcess(ctx, manager, "Select process to pin");
        if (!processId) return;
      }
      if (!processId) return;
      dockActions.setFocus(processId);
    }
  });
}

